```tsx
import "./ChipFilter.css";

export interface ChipOption {
  readonly value: string;
  readonly label: string;
}

export interface ChipFilterProps {
  readonly label: string;
  readonly options: readonly ChipOption[];
  readonly selected: readonly string[];
  readonly onToggle: (value: string) => void;
}

export function ChipFilter({ label, options, selected, onToggle }: ChipFilterProps) {
  const selectedValues = new Set<string>(selected);

  return (
    <fieldset className="chip-filter">
      <legend className="chip-filter__legend">{label}</legend>
      <div className="chip-filter__chips">
        {options.map((option) => {
          const isOn = selectedValues.has(option.value);
          const className = isOn
            ? "chip-filter__chip chip-filter__chip--on"
            : "chip-filter__chip";

          return (
            <button
              key={option.value}
              type="button"
              className={className}
              aria-pressed={isOn}
              onClick={() => onToggle(option.value)}
            >
              <span className="chip-filter__mark" aria-hidden="true" />
              <span className="chip-filter__text">{option.label}</span>
            </button>
          );
        })}
      </div>
    </fieldset>
  );
}
```

