/* Day theme is the default. Night theme applies when an ancestor carries data-theme="night". */

.chip-filter {
  --chip-fg: #2b2a26;
  --chip-muted: #6b675c;
  --chip-border: #d6d0bf;
  --chip-bg: #fbf9f3;
  --chip-hover-bg: #f1ede2;
  --chip-on-bg: #2f6f6a;
  --chip-on-fg: #f7fbfa;
  --chip-on-border: #2f6f6a;
  --chip-focus: #2f6f6a;
  --chip-mark-off: #b9b29e;
  --chip-mark-on: #f7fbfa;

  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
  color: var(--chip-fg);
}

[data-theme="night"] .chip-filter {
  --chip-fg: #d9dce3;
  --chip-muted: #9097a6;
  --chip-border: #3a3f4b;
  --chip-bg: #22252e;
  --chip-hover-bg: #2b2f3a;
  --chip-on-bg: #7fb8b0;
  --chip-on-fg: #13201f;
  --chip-on-border: #7fb8b0;
  --chip-focus: #9fd3cb;
  --chip-mark-off: #4d5361;
  --chip-mark-on: #13201f;
}

.chip-filter__legend {
  padding: 0;
  margin-bottom: 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--chip-muted);
}

.chip-filter__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.chip-filter__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.25rem;
  padding: 0.375rem 0.875rem;
  border: 1px solid var(--chip-border);
  border-radius: 999px;
  background: var(--chip-bg);
  color: var(--chip-fg);
  font: inherit;
  font-size: 0.875rem;
  line-height: 1.2;
  cursor: pointer;
  user-select: none;
  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    color 160ms ease;
}

.chip-filter__chip:hover {
  background: var(--chip-hover-bg);
}

.chip-filter__chip:focus-visible {
  outline: 2px solid var(--chip-focus);
  outline-offset: 2px;
}

.chip-filter__chip--on,
.chip-filter__chip--on:hover {
  background: var(--chip-on-bg);
  border-color: var(--chip-on-border);
  color: var(--chip-on-fg);
}

.chip-filter__mark {
  display: inline-block;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--chip-mark-off);
  transition: background-color 160ms ease;
}

.chip-filter__chip--on .chip-filter__mark {
  background: var(--chip-mark-on);
}

@media (prefers-reduced-motion: reduce) {
  .chip-filter__chip,
  .chip-filter__mark {
    transition: none;
  }
}
